USE empleados_db;

INSERT INTO `provincias` (
    `id`,
    `nombre`,
    `capital`,
    `descripcion`,
    `poblacion`,
    `superficie`,
    `latitud`,
    `longitud`,
    `id_region`,
    `created_at`,
    `updated_at`
) VALUES
(1,'Azuay','Cuenca','Es llamada la Atenas del Ecuador por su arquitectura, su diversidad cultural, su aporte a las artes, ciencias y letras ecuatorianas y por ser el lugar de nacimiento de muchos personajes ilustres de la sociedad ecuatoriana','569.42',122.00,-2.902222,-79.005261,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(2,'Bolivar','Guaranda','Bolívar es una provincia del centro de Ecuador, en la cordillera occidental de los Andes. Su capital es la ciudad de Guaranda. La Provincia de Bolívar se llama así en honor al Libertador Simón Bolívar.','183 641',3254.00,-1.600000,-79.000000,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(3,'Cañar','Azogues','La provincia destaca como uno de los sitios turisticos mas importantes del pais, destacandose entre otros la Fortaleza de Ingapirca, la Laguna de Culebrillas y la ciudad de Azogues.','33848.00',3908.00,-2.733333,-78.833333,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(4,'Carchi','Tulcán','Carchi es una provincia ecuatoriana situada al norte del Ecuador en la frontera con Colombia. Su capital es la ciudad de Tulcán.','82734.00',3783.00,0.811667,-77.718611,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(5,'Chimborazo','Riobamba','En esta provincia se encuentran varias de las cumbres mas elevadas del pais, como el Carihuairazo, el Altar, Igualata, Sangay, entre otros, que en algunos casos comparte con otras provincias.','223586.00',6487.00,-1.666667,-78.650000,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(6,'Cotopaxi','Latacunga','La provincia toma el nombre del volcán más grande e importante de su territorio, el volcán Cotopaxi.','409 205',6569.00,-0.933333,-78.616667,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(7,'El Oro','Machala','La capital de la provincia de El Oro es la ciudad de Machala, quinta ciudad del país, considerada como la capital bananera del mundo.','260528.00',6188.00,-3.266669,-79.966700,2,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(8,'Esmeraldas','Esmeraldas','Provincia del Ecuador situada en su costa noroccidental, conocida popularmente como la provincia verde.','189504.00',15954.00,-0.966667,-79.650000,2,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(9,'Galápagos','P. Baquerizo Moreno','Es el mayor centro turístico del Ecuador, así como también una de las reservas ecológicas más grandes e importantes del planeta.','5600.00',8010.00,-0.666667,-90.550000,3,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(10,'Guayas','Guayaquil','Es el mayor centro comercial e industrial del Ecuador.','2526927.00',17139.00,-2.200000,-79.966700,2,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(11,'Imbabura','Ibarra','La provincia también es conocida por sus contrastes poblacionales y ha sido núcleo de artesanías y cultura.','181722.00',4599.00,0.350000,-78.133333,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(12,'Loja','Loja','Loja es una ciudad del Ecuador, capital de la provincia y cantón Loja, con rica tradición en las artes.','206.83',57.00,-3.833000,-80.067000,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(13,'Los Rios','Babahoyo','Los Ríos es una de las 24 provincias de la República del Ecuador, localizada en la Región Costa del país.','778115.00',6254.00,-1.766669,-79.450000,2,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(14,'Manabí','Portoviejo','Manabí es una provincia ecuatoriana localizada en el centro-noroeste del Ecuador continental.','1369780.00',18400.00,-1.052219,-80.450600,2,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(15,'Morona Santiago','Macas','Morona Santiago es una de las 24 provincias que conforman la República del Ecuador.','147940.00',25690.00,-2.366667,-78.133333,4,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(16,'Napo','Tena','La provincia de Napo es una de las provincias de la región amazónica ecuatoriana.','103697.00',13271.00,0.989000,-77.815900,4,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(17,'Orellana','Francisco de Orellana','Orellana es una provincia de la Región Amazónica del Ecuador.','136396.00',20773.00,-0.933333,-75.666667,4,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(18,'Pastaza','Puyo','Pastaza es una de las 24 provincias que conforman la República del Ecuador, situada en la Región Amazónica.','83933.00',29520.00,-1.066667,-78.001111,4,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(19,'Pichincha','Quito','La Provincia de Pichincha es una de las 24 provincias que conforman la República del Ecuador.','2576287.00',9612.00,-0.250000,-78.583333,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(20,'Santa Elena','Santa Elena','Santa Elena es una provincia de la costa de Ecuador creada el 7 de noviembre de 2007.','308693.00',3763.00,-2.226700,-80.858300,2,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(21,'Santo Domingo de los Tsáchilas','Santo Domingo','La Provincia de Santo Domingo de los Tsáchilas forma parte de la Región Costa.','410937.00',4180.00,-0.333333,-79.250000,2,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(22,'Sucumbíos','Nueva Loja','Sucumbíos es una provincia del nor-oriente del Ecuador.','176472.00',18612.00,-0.083333,-76.883333,4,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(23,'Tungurahua','Ambato','Tungurahua es una de las 24 provincias que conforman la República del Ecuador.','504583.00',3334.00,-1.233333,-78.616667,1,'2026-04-04 06:20:11','2026-04-04 06:20:11'),
(24,'Zamora Chinchipe','Zamora','Zamora Chinchipe es una provincia de Ecuador ubicada en el sur-oriente de la Amazonía ecuatoriana.','91376.00',10556.00,-2.883333,-79.000000,4,'2026-04-04 06:20:11','2026-04-04 06:20:11');

